import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"Linux 性能调优","description":"","frontmatter":{"title":"Linux 性能调优","order":60},"headers":[],"relativePath":"sde/sre/tuning.md","filePath":"sde/sre/tuning.md"}`),a={name:`sde/sre/tuning.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="服务器莫名卡顿排查" tabindex="-1">服务器莫名卡顿排查 <a class="header-anchor" href="#服务器莫名卡顿排查" aria-label="Permalink to “服务器莫名卡顿排查”">​</a></h1><p>&quot;服务器偶尔卡一下又恢复了&quot;是最难排查的性能问题类——没有崩溃、没有错误日志、监控曲线只有不明显的毛刺。这类问题的排查方法论是：<strong>先定位&quot;卡&quot;的类型（CPU/内存/IO/网络/锁），再定位时刻（什么时候卡），最后定位到具体进程或内核路径</strong>。顺序反了就会陷入&quot;什么都查了什么都正常&quot;的循环。</p><h2 id="第一步-确认卡顿的形态" tabindex="-1">第一步：确认卡顿的形态 <a class="header-anchor" href="#第一步-确认卡顿的形态" aria-label="Permalink to “第一步：确认卡顿的形态”">​</a></h2><p>&quot;卡&quot;这个词掩盖了完全不同的故障模式。先问用户或观察现象把它归类：</p><p><strong>交互卡</strong>（SSH 登录慢、命令响应慢）→ 通常是 CPU 饱和（load 高）、内存回收（swap 活跃）、或 IO 等待——系统级问题。<strong>吞吐卡</strong>（请求延迟升高但系统看起来空闲）→ 通常是锁竞争、连接池耗尽、下游依赖慢——应用级问题。<strong>周期性卡</strong>（每隔 N 分钟/小时卡一次）→ 定时任务（cron、日志轮转、备份）、GC、或监控采集本身——周期性指纹是最有价值的线索。<strong>随机卡</strong>（无规律）→ 竞态类（锁、连接耗尽）或外部依赖（网络抖动、共享存储邻居噪声）。</p><h2 id="第二步-锁定时刻" tabindex="-1">第二步：锁定时刻 <a class="header-anchor" href="#第二步-锁定时刻" aria-label="Permalink to “第二步：锁定时刻”">​</a></h2><p>瞬时的卡顿在平均值监控里不可见——1 分钟采样率的监控会漏掉 5 秒的卡顿。排查手段按时间精度递进：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># uptime/loadavg 的三时间窗——1分钟 vs 15分钟的差值指示&quot;正在发生&quot;还是&quot;已经过去&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uptime</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># vmstat 的 r 列（运行队列）和 wa 列（IO等待）——1秒间隔持续观察</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vmstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 卡顿发生时的第一手数据：sysstat 的历史（如果部署了 sadc）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/sa/sa14</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # 当天的队列数据</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                        # 页回收活动</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                        # 每设备 IO</span></span></code></pre></div><p>如果卡顿还会发生，<code>vmstat 1</code> 挂在终端上等待下一次卡顿出现是最朴素也最有效的手段——卡顿发生那一秒的 r/wa/si 列的突变直接指向方向。</p><h2 id="第三步-按方向深入" tabindex="-1">第三步：按方向深入 <a class="header-anchor" href="#第三步-按方向深入" aria-label="Permalink to “第三步：按方向深入”">​</a></h2><h3 id="cpu-方向" tabindex="-1">CPU 方向 <a class="header-anchor" href="#cpu-方向" aria-label="Permalink to “CPU 方向”">​</a></h3><p>load 高但 CPU 使用率不高 → 不是计算瓶颈而是<strong>等待</strong>——load 统计的是&quot;运行队列 + 不可中断睡眠&quot;（Linux 的 load 含 D 状态进程），高 load + 低 CPU% 的组合指向 IO 等待或内存问题。</p><p>CPU 使用率的细分比总量更有信息量：<code>%iowait</code> 高 → IO 等待（转 IO 方向）；<code>%sys</code> 高 → 内核态消耗（syscall 风暴、锁自旋、软中断）；<code>%soft</code> 高 → 网络软中断（可能有中断风暴）；<code>%steal</code> 高 → 虚机邻居抢占（云上宿主机超卖——你控制不了但至少能确认）。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 按 CPU 核查看——单核打满 vs 均匀分布是完全不同的问题</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mpstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALL</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 单核 100% softirq：中断亲和把流量集中到一个核（RSS/RPS 配置问题）</span></span></code></pre></div><h3 id="内存方向" tabindex="-1">内存方向 <a class="header-anchor" href="#内存方向" aria-label="Permalink to “内存方向”">​</a></h3><p>内存不足的卡顿指纹是<strong>回收活动</strong>而非使用率——使用率 90% 但无回收则完全健康（缓存占满），使用率 70% 但疯狂回收则严重卡顿。关键指标：<code>pgscan/pgsteal</code>（直接回收——进程在分配路径上同步等回收，延迟飙升的主因）、<code>si/so</code>（swap 活动）、<code>major fault</code>（需要从磁盘读页）。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vmstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">        # si/so 非零 = swap 活跃</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">          # pgscand（直接回收）非零 = 分配路径上的同步痛苦</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/pressure/vm</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">   # PSI（Pressure Stall Information）——内核直接告诉你&quot;有多少时间浪费在等内存&quot;</span></span></code></pre></div><p>PSI（内核 4.20+）是&quot;莫名卡顿&quot;的利器：<code>some</code> 行是&quot;至少一个任务在等待&quot;，<code>full</code> 行是&quot;所有任务都在等&quot;——<code>full</code> 的任何非零读数都是硬证据。CPU 和 IO 也有对应的 PSI 文件。</p><h3 id="io-方向" tabindex="-1">IO 方向 <a class="header-anchor" href="#io-方向" aria-label="Permalink to “IO 方向”">​</a></h3><p><code>iowait</code> 高 + 设备 util 高 → 磁盘真实饱和；<code>iowait</code> 高 + 设备 util 不高 → IO 请求的<strong>并发排队</strong>问题（队列深度、条带不均）或<strong>远端存储</strong>的延迟（NVSAN、网络存储抖动）。注意 util 的陷阱：SSD/NVMe 的并行能力使 util 100% 不代表饱和（设备可以同时处理很多请求）——看 <code>await</code>（每次 IO 平均耗时）和队列深度更可靠。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iostat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">        # await、aqu-sz（队列深度）、%util</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pidstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">        # 哪个进程在产生 IO</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iotop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">            # 实时 IO 排名</span></span></code></pre></div><h3 id="网络-锁方向" tabindex="-1">网络/锁方向 <a class="header-anchor" href="#网络-锁方向" aria-label="Permalink to “网络/锁方向”">​</a></h3><p>延迟升高但系统资源全部空闲 → 应用层问题。网络：<code>ss -ti</code> 看 RTT 和重传（远端慢还是本端慢）、conntrack 表满（<code>nf_conntrack: table full</code> 的 dmesg）、TIME_WAIT 堆积。锁/依赖：<code>perf lock</code>（内核锁）、应用级的连接池/线程池指标、<code>off-cpu</code> 分析（火焰图看&quot;不在 CPU 上的时间花在哪&quot;——pidstat 的 %wait 列、eBPF 的 offcputime）。</p><h2 id="定期复查的工具箱" tabindex="-1">定期复查的工具箱 <a class="header-anchor" href="#定期复查的工具箱" aria-label="Permalink to “定期复查的工具箱”">​</a></h2><p>一次性排查靠上述命令组合；持续防护靠基础设施：</p><p><strong>eBPF 类工具</strong>把&quot;卡顿时刻在干什么&quot;的可见性推到了新高度——<code>biolatency</code>（IO 延迟直方图）、<code>runqlat</code>（调度延迟——进程等多久才上 CPU）、<code>offcputime</code>（off-CPU 时间火焰图）。卡顿是&quot;延迟毛刺&quot;类问题时，直方图的尾部分布比平均值敏感得多。</p><p><strong>trace 类的最后手段</strong>：卡顿仍然无法定位时，<code>perf record -g</code> 定时采样 + 卡顿时刻对比，或者 <code>ftrace</code> 的 <code>irqsoff</code>/<code>preemptoff</code> tracer（关中断/关抢占最长的时段——延迟毛刺的内核侧来源）。这类工具开销大，只在定向排查时短时开启。</p><p><strong>排查笔记的习惯</strong>：&quot;莫名卡顿&quot;往往最终定位到朴素的根因——备份任务与业务高峰重叠、cron 每小时的日志压缩、某个容器的日志打满磁盘、swap 分区在一个&quot;以为没有 swap&quot;的机器上。系统性方法的价值不是把简单问题复杂化，而是确保简单原因被系统性排除——按 CPU/内存/IO/网络/锁的顺序过一遍，简单原因自然浮出。</p>`,28)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};